const { execFileSync } = require('child_process');
const projectRoot = process.env.VIDEO_WORKFLOW_ROOT || 'D:\\抖音信息视频工作流';
const scriptPath = `${projectRoot}\\scripts\\sync_video_library.js`;
const stdout = execFileSync(process.execPath, [scriptPath], { cwd: projectRoot, encoding: 'utf8', windowsHide: true, maxBuffer: 16 * 1024 * 1024, env: { ...process.env, VIDEO_WORKFLOW_ROOT: projectRoot } });
return [{ json: { stdout } }];

